SELECT SOURCE_ID,BATCH_SHA256,COUNT(*) AS N_ROWS,COUNT(DISTINCT ROW_INDEX) AS UNIQUE_ROW_INDICES,COUNT(DISTINCT ROW_SHA256) AS UNIQUE_ROW_HASHES,MIN(EVENT_TIME_TEXT) AS FIRST_EVENT_TEXT,MAX(EVENT_TIME_TEXT) AS LAST_EVENT_TEXT,COUNT_IF(NULLIF(TRIM(AVAILABLE_AT_TEXT),'') IS NULL) AS MISSING_AVAILABILITY,COUNT_IF(TRY_PARSE_JSON(PAYLOAD_JSON) IS NULL) AS INVALID_JSON,MIN(TO_JSON(OBJECT_KEYS(TRY_PARSE_JSON(PAYLOAD_JSON)))) AS PAYLOAD_KEYS,MIN(LOADED_AT) AS FIRST_LOAD,MAX(LOADED_AT) AS LAST_LOAD FROM VECTOR_RESEARCH.RAW.SOURCE_RECORDS GROUP BY 1,2 ORDER BY 1,2
